#[cfg(test)]
mod tests {
    use rigorix_engine::effect_commitment::infrastructure::{
        HttpEffectLedger, HttpEffectLedgerConfig,
    };
    use rigorix_engine::effect_commitment::interfaces::EffectCommitmentLedger;

    #[test]
    fn test_httpeffectledger_is_defined() {
        let cfg = HttpEffectLedgerConfig::new(
            "https://commitment.example",
            5_000,
            65_536,
            Some("token".to_string()),
        );
        let ledger = HttpEffectLedger::new(cfg);
        assert_eq!(ledger.config().base_url, "https://commitment.example");
        assert_eq!(ledger.config().timeout_ms, 5_000);
        assert_eq!(ledger.config().max_response_body_bytes, 65_536);
        assert_eq!(ledger.config().auth_token(), Some("token"));

        let _port: &dyn EffectCommitmentLedger = &ledger;
    }

    #[test]
    fn test_httpeffectledger_interacts_with_effectcommitmentledger() {
        fn assert_impl<T: EffectCommitmentLedger>() {}
        assert_impl::<HttpEffectLedger>();

        // Credentials are never rendered by Debug (fail-closed transport discipline).
        let cfg = HttpEffectLedgerConfig::new(
            "https://commitment.example",
            1_000,
            1_024,
            Some("super-secret".to_string()),
        );
        let rendered = format!("{cfg:?}");
        assert!(!rendered.contains("super-secret"));
        assert!(rendered.contains("<redacted>"));
    }
}
